#include "dei_sc_private.h"
/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
Boolean dei_sc_init_nvfs (void)
{

  static  Dei_Sc      cur_dei_sc         ;

          Boolean         status         = FALSE ;


  if(nvfs_rd(nvfs_rem_dei , &dei_sc) != NVFS_OK)
    {
      
      status |= nvfs_wr_create( nvfs_rem_dei  , &cur_dei_sc , sizeof (Dei_Sc) ) == NVFS_OK ;   
           
    }

  if(status)
    {
      status |= nvram_usr_commit() ;
    }

  status |= nvfs_rd(nvfs_rem_dei , &dei_sc) == NVFS_OK ;


  load_sn:
  {	
   	Id_Entry id ;

    nvfs_rd( nvfs_id , &id ); 

    #define D0	((id.item.serial[0] - '0')*1000000)
	#define D1	((id.item.serial[1] - '0')*100000)
	#define D2	((id.item.serial[2] - '0')*10000)
	#define D3	((id.item.serial[3] - '0')*1000)
	#define D4	((id.item.serial[4] - '0')*100)
	#define D5	((id.item.serial[5] - '0')*10)
	#define D6	((id.item.serial[6] - '0')*1)		
				
	dei_sc.car_sn = (UInt16)( D0+D1+D2+D3+D4+D5+D6 ) ;

	TRACE_DEI_SC("\n\r[LIB.DEI_SC] CAR SN : %07d\n\r" , dei_sc.car_sn );

	TRACE_DEI_SC("\n\r[LIB.DEI_SC] MODULE SN : %07d\n\r" , D0+D1+D2+D3+D4+D5+D6 );    	

	#undef D0
	#undef D1
	#undef D2
	#undef D3
	#undef D4
	#undef D5
	#undef D6		
  };	

  return status ;

}

